param([switch]$KeepContainer)
$ErrorActionPreference='Stop';$root=[IO.Path]::GetFullPath((Join-Path $PSScriptRoot '\..\..'));$c='nello_clinical_attachments_test'
$m=@('20260813040000_d1_d5_clinical_science.sql','20260813041000_d6_d7_meal_plan_integrity.sql','20260813042000_d8_d9_plan_template_versioning.sql','20260813043000_d10_meal_plan_documents.sql','20260813044000_d_advisor_hardening.sql','20260813045000_c8_d_text_encoding_repair.sql','20260813050000_d_scientific_source_url_repair.sql','20260813060000_c6_d10_adversarial_hardening.sql')|%{Join-Path $root "supabase\migrations\$_"};$tests=@('d1_d10_clinical_prescription_matrix.sql','c6_d10_adversarial_hardening_matrix.sql')|%{Join-Path $root "supabase\tests\$_"}
try{& (Join-Path $PSScriptRoot 'verify-c8-privacy-requests.ps1') -KeepContainer;if($LASTEXITCODE -ne 0){throw 'C8 regression failed'};for($i=0;$i -lt $m.Count;$i++){docker cp $m[$i] "${c}:/tmp/d-$i.sql"|Out-Null;docker exec -e PGPASSWORD=postgres $c psql --single-transaction -v ON_ERROR_STOP=1 -U supabase_admin -d postgres -f "/tmp/d-$i.sql"|Out-Null;if($LASTEXITCODE -ne 0){throw "D migration $i failed"}};for($i=0;$i -lt $tests.Count;$i++){docker cp $tests[$i] "${c}:/tmp/d-test-$i.sql"|Out-Null;docker exec -e PGPASSWORD=postgres $c psql -v ON_ERROR_STOP=1 -U supabase_admin -d postgres -f "/tmp/d-test-$i.sql";if($LASTEXITCODE -ne 0){throw "D regression matrix $i failed"}};Write-Output 'C6-D10 adversarial clinical, privacy and prescription matrices approved.'}finally{if(-not $KeepContainer){docker rm -f $c 2>$null|Out-Null}}
